#!/usr/bin/env python3
"""Authoring source for Merzlyak 2022 base §2, visually checked PDF15–17.

This generates drafts, never review approval. Numeric coordinates describe
the indicated example/counterexample; the reasoning covers the full problem.
"""
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'stereo-course/merzlyak-10-base/lessons'

def view(label, segments=None, polygon=None, points=None):
    d = {'label': label}
    if segments: d['segments'] = segments
    if polygon: d['polygon'] = polygon
    if points: d['points'] = points
    return d

def model(points, edges, views, *, faces=None, labels=None, planar=False):
    d = {'points': points, 'edges': edges, 'views': {'neutral': view('Исходная конфигурация'), **views},
         'labelNames': labels if labels is not None else [x for x in points if not x.startswith('_')]}
    if faces: d['faces'] = faces
    if planar: d['planar'] = True
    return d

def plane(points, prefix='_p', xmin=-3, xmax=3, ymin=-2, ymax=2, z=0):
    names = [prefix+str(i) for i in range(4)]
    for n,p in zip(names, [(xmin,ymin,z),(xmax,ymin,z),(xmax,ymax,z),(xmin,ymax,z)]): points[n]=list(p)
    return names

def step(title, prompt, explanation, reason, v='neutral', kind='theorem'):
    return {'title':title,'prompt':prompt,'explanation':explanation,
            'justifications':[{'kind':kind,'text':reason}], 'view':v}

def lesson(n, title, statement, goal, m, steps, hint, *, caption=None, accepted=None):
    page = 14 if n<=2 else 15 if n<=14 else 16
    answer = {'mode':'manual','prompt':'Запиши вывод и его обоснование. Запись сохраняется для обсуждения с преподавателем; доказательство автоматически не оценивается.'}
    if accepted:
        answer={'mode':'exact','prompt':goal+' Введи только число без единиц.','accepted':accepted,
                'feedback':'Проверь, какие величины связаны в решении, и выполни вычисление ещё раз.'}
    d={'schemaVersion':1,'revision':1,'id':f'ex-02-{n:03}','kind':'exercise','title':f'№ 2.{n}. {title}',
       'status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'main','exercise':f'2.{n}',
       'chapter':'Глава 1. Введение в стереометрию','printedPages':[page],'pdfPages':[page+1]},
       'statement':{'text':statement,'goal':goal},
       'visualization':{'type':'scene3d','caption':caption or 'Это отдельная схема к задаче. Прямые и плоскости продолжаются за границами нарисованных фрагментов; величины не определяют измерением рисунка.', 'model':m},
       'help':[{'id':'help-1','question':'С чего начать?','text':hint}],
       'steps':[dict(s,id=f'step-{i+1}') for i,s in enumerate(steps)],'answer':answer,
       'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/f'ex-02-{n:03}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')

# 2.1: the line-point theorem has an essential outside-the-line hypothesis.
p={'B':[-2,0,0],'C':[2,0,0],'A':[0,1.5,0],'H':[0,0,0]}; a=plane(p)
p.update({'_q0':[-3,0,-1.5],'_q1':[3,0,-1.5],'_q2':[3,0,1.5],'_q3':[-3,0,1.5]}); b=['_q0','_q1','_q2','_q3']
lesson(1,'Прямая и точка: два случая','Сколько плоскостей можно провести через данные прямую и точку?',
 'Укажи число плоскостей в зависимости от положения точки.',model(p,[['B','C']],{'outside':view('Точка A вне прямой BC',polygon=a,points=['A']), 'online':view('Если заданная точка H лежит на BC, плоскость можно менять',polygon=b,points=['H'])},faces=[a]),[
 step('Проверим положение точки','Обязательно ли данная точка лежит вне прямой?','Нет. В условии это не сказано, поэтому рассматриваем два случая. В модели A показывает внешнюю точку, H — точку на прямой.','Условие не ограничивает взаимное расположение прямой и точки.','outside','given'),
 step('Точка вне прямой','Какой результат §2 можно применить?','Через прямую и не лежащую на ней точку проходит ровно одна плоскость. Поэтому для внешней точки ответ: одна.','Теорема 2.1.','outside'),
 step('Точка на прямой','Добавляет ли точка H новое ограничение к требованию содержать BC?','Нет: любая плоскость через прямую уже содержит H. Таких плоскостей бесконечно много: плоскость можно поворачивать вокруг BC. Ответ: одна для точки вне прямой; бесконечно много для точки на прямой.','Пучок плоскостей через одну прямую.','online')], 'Сначала раздели случаи: точка принадлежит прямой или не принадлежит ей.')

p={'A':[-2,0,0],'B':[0,0,0],'C':[2,0,0],'D':[0,1.5,0]}; a=plane(p)
p.update({'_q0':[-3,0,-1.5],'_q1':[3,0,-1.5],'_q2':[3,0,1.5],'_q3':[-3,0,1.5]}); b=['_q0','_q1','_q2','_q3']
lesson(2,'Плоскости через три точки одной прямой','Докажите, что через три точки, лежащие на одной прямой, можно провести плоскость. Сколько можно провести таких плоскостей?',
 'Докажи существование плоскости и укажи число таких плоскостей.',model(p,[['A','C']],{'first':view('Прямая AC и внешняя точка D задают одну плоскость',polygon=a,points=['D']), 'second':view('Другая плоскость через ту же прямую',polygon=b)},faces=[a]),[
 step('Выберем вспомогательную точку','Где взять точку D для применения теоремы 2.1?','Обозначим общую прямую трёх точек через a. Выберем точку D вне a. Такая точка существует в пространстве.','Существование точек вне данной прямой.','first'),
 step('Проведём плоскость','Какие объекты определяют эту плоскость?','Прямая a и внешняя точка D определяют плоскость. Она содержит всю прямую a, поэтому содержит каждую из трёх данных точек. Существование доказано.','Теорема 2.1.','first'),
 step('Посчитаем плоскости','Обязаны ли все плоскости через a совпадать?','Нет. Поворачивая плоскость вокруг a, получаем бесконечно много различных плоскостей; все три точки остаются на оси поворота и принадлежат каждой из них. Ответ: бесконечно много.','Плоскости через одну прямую образуют пучок.','second')], 'Не применяй аксиому о трёх неколлинеарных точках: здесь точки лежат на одной прямой. Добавь внешнюю точку.')

p={'A':[-2,0,0],'B':[2,0,0],'C':[0,-1.5,0],'D':[0,2,0],'O':[0,0,0]}
lesson(3,'Соединяющие прямые в общей плоскости','Прямые AB и CD пересекаются. Докажите, что прямые AC и BD лежат в одной плоскости.',
 'Обоснуй принадлежность AC и BD одной плоскости.',model(p,[['A','B'],['C','D']],{'plane':view('Плоскость двух пересекающихся прямых',polygon=['A','C','B','D']), 'ac':view('Две точки прямой AC в плоскости',segments=[['A','C']]), 'bd':view('Две точки прямой BD в плоскости',segments=[['B','D']])},planar=True),[
 step('Зададим плоскость','Почему AB и CD лежат в одной плоскости?','Две пересекающиеся прямые AB и CD определяют единственную плоскость α.','Теорема 2.2.','plane'),
 step('Проверим AC','Какие две точки AC уже принадлежат α?','A принадлежит AB, C принадлежит CD. Обе исходные прямые лежат в α, значит, A,C∈α. Поэтому вся прямая AC лежит в α.','Аксиома A3: прямая через две точки плоскости лежит в ней.','ac'),
 step('Проверим BD','Повтори рассуждение для B и D.','B∈AB⊂α и D∈CD⊂α, поэтому BD⊂α. Таким образом, AC и BD лежат в общей плоскости α.','Аксиома A3.','bd')], 'Сначала назови плоскость двух исходных пересекающихся прямых, затем используй по две точки новых прямых.')

def circle_counterexample():
    p={'O':[0,0,0],'A':[-2,0,0],'B':[2,0,0],'C':[0,0,2]}
    ring=[]
    for i in range(32):
        k=f'_r{i}';ring.append(k);p[k]=[2*math.cos(2*math.pi*i/32),0,2*math.sin(2*math.pi*i/32)]
    a=plane(p,xmin=-2.7,xmax=2.7,ymin=-1.3,ymax=1.3)
    edges=[[ring[i],ring[(i+1)%32]] for i in range(32)]+[['A','B']]
    return p,a,edges
p,a,e=circle_counterexample()
lesson(4,'Хорда может оказаться диаметром','Центр O и хорда AB окружности лежат в некоторой плоскости. Лежит ли в этой плоскости любая точка данной окружности?',
 'Определи, следует ли утверждение из условия; разбери особый случай.',model(p,e,{'diameter':view('Диаметр AB и центр O лежат в α',polygon=a,points=['O','A','B']), 'outside':view('Точка C окружности находится вне α',points=['C'])},faces=[a]),[
 step('Хорда не проходит через центр','Что можно сказать о трёх точках A,B,O в этом случае?','Сначала рассмотрим случай, отличный от показанного в модели: AB не является диаметром. Тогда O не лежит на прямой AB. Точки A,B,O определяют единственную плоскость. И плоскость окружности, и данная плоскость содержат эти точки, поэтому совпадают. В этом случае ответ «да».','Единственность плоскости через три неколлинеарные точки.','diameter'),
 step('Проверим диаметр','Можно ли утверждать, что O всегда вне AB?','Нельзя: хорда AB может быть диаметром. Тогда A,O,B лежат на одной прямой. Данная плоскость может проходить через диаметр и отличаться от плоскости окружности.','Определение диаметра.','diameter','definition'),
 step('Построим контрпример','Где расположена точка C в модели?','Окружность показана в вертикальной плоскости, а α — горизонтальная плоскость через её диаметр AB. Центр O и AB лежат в α, но верхняя точка C окружности — вне α. Следовательно, из условия ответ «да» не следует.','Один пример с выполненным условием и ложным выводом опровергает общее утверждение.','outside')], 'Вспомни: диаметр тоже является хордой.',caption='Контрпример с диаметром AB: окружность вертикальна, данная плоскость α проходит через AB горизонтально. Окружность изображена замкнутой ломаной из мелких звеньев; вращай модель, чтобы увидеть точку C вне α.')

p,a,e=circle_counterexample();p['B']=[0,0,2];p['C']=[2,0,0]
e=[x for x in e if x!=['A','B']]+[['A','C'],['A','B'],['B','C']]
lesson(5,'Гипотенуза и центр окружности','Сторона AC и центр O описанной окружности треугольника ABC лежат в плоскости α. Лежит ли в этой плоскости вершина B?',
 'Определи, обязана ли вершина B принадлежать α.',model(p,e,{'diameter':view('AC — диаметр, O — его середина',segments=[['A','C']],polygon=a,points=['O']), 'triangle':view('Прямоугольный треугольник ABC может выходить из α',polygon=['A','B','C'])},faces=[a]),[
 step('Центр вне AC','Когда единственность плоскости сразу помогает?','Сначала рассмотрим случай, отличный от показанного в модели: O не лежит на AC. Тогда A,C,O неколлинеарны. Они определяют плоскость треугольника, которая поэтому совпадает с α. Тогда B∈α.','Единственность плоскости через три неколлинеарные точки.','diameter'),
 step('Центр лежит на AC','Какая сторона описанного треугольника проходит через центр окружности?','Если O лежит на AC, то AC — диаметр описанной окружности, а ∠ABC=90°. Так бывает у прямоугольного треугольника с гипотенузой AC.','Вписанный угол, опирающийся на диаметр, прямой.','triangle'),
 step('Проверим вывод','Обязана ли α совпадать с плоскостью прямоугольного треугольника?','Нет. Через гипотенузу AC можно провести другую плоскость α. Она содержит и O, но не содержит B. Модель показывает именно такой случай. Поэтому без дополнительного условия утверждать B∈α нельзя.','Через прямую проходит бесконечно много плоскостей.','triangle')], 'Отдельно рассмотри прямоугольный треугольник, у которого AC — гипотенуза.',caption='Контрпример: прямоугольный треугольник ABC и его описанная окружность вертикальны, плоскость α проходит через гипотенузу AC горизонтально. Центр O лежит на AC, вершина B — вне α.')

p={'O':[0,0,0],'A':[-2,0,0],'B':[2,0,0],'C':[0,-2,0],'D':[0,2,0],'T':[0,0,2]};a=plane(p)
lesson(6,'Прямая через общую точку','Прямые a и b пересекаются. Все ли прямые, пересекающие прямые a и b, лежат в одной плоскости?',
 'Проверь утверждение и объясни роль общей точки пересечения.',model(p,[['A','B'],['C','D'],['O','T']],{'plane':view('a=AB и b=CD лежат в α',polygon=a), 'counter':view('OT пересекает обе прямые в O, но выходит из α',segments=[['O','T']],points=['O','T']), 'two':view('AD пересекает a и b в разных точках',segments=[['A','D']])},faces=[a]),[
 step('Плоскость исходных прямых','Как задать общую плоскость a и b?','Две пересекающиеся прямые a,b определяют плоскость α. Обозначим их общую точку O.','Теорема 2.2.','plane'),
 step('Два разных пересечения','Что будет, если новая прямая пересекает a в A и b в D, причём A≠D?','Тогда новая прямая имеет две разные точки A,D в α, поэтому лежит в α. Но условие задачи не требует разных точек пересечения.','Аксиома A3.','two'),
 step('Пересечение в общей точке','Выбери T вне α. Что делает прямая OT?','OT пересекает и a, и b в точке O. При этом T∉α, значит, OT не лежит в α. Следовательно, ответ «нет»: не все такие прямые лежат в одной плоскости.','Контрпример через общую точку O.','counter')], 'Новая прямая может пересекать обе исходные прямые в одной и той же точке.')

p={'B':[-2,0,0],'C':[2,0,0],'A':[0,2,0],'M':[.7,0,0]}
lesson(7,'Все секущие через внешнюю точку','Даны прямая a и точка A вне её. Докажите, что все прямые, которые проходят через точку A и пересекают прямую a, лежат в одной плоскости.',
 'Назови одну общую плоскость и докажи принадлежность любой такой прямой.',model(p,[['B','C'],['A','B'],['A','C']],{'plane':view('a=BC и внешняя точка A задают α',polygon=['A','B','C']), 'any':view('Произвольная точка M на a и прямая AM',segments=[['A','M']],points=['M'])},planar=True),[
 step('Зададим общую плоскость','Почему плоскость через a и A существует и единственна?','Точка A не лежит на a. По теореме 2.1 существует единственная плоскость α, содержащая A и a.','Теорема 2.1.','plane'),
 step('Возьмём любую секущую','Как обозначить её точку пересечения с a?','Пусть l — любая прямая через A, пересекающая a в M. M∈a⊂α и A∈α. Кроме того, A≠M, так как A∉a.','Условие задачи и выбор произвольной прямой l.','any','given'),
 step('Применим аксиому','Почему это доказывает утверждение сразу для всех таких прямых?','Через две различные точки A,M плоскости α проходит прямая l, поэтому l⊂α. Мы не ограничивали выбор l: рассуждение верно для каждой прямой указанного вида.','Аксиома A3.','any')], 'Выбирай одну произвольную секущую и докажи, что она лежит в заранее выбранной плоскости.')

p={'A':[0,0,0],'B':[-2,0,0],'C':[0,2,0],'D':[-.7,1.3,0],'_m':[1,0,0],'_n':[0,-1,0]}
lesson(8,'Точка на соединяющей прямой','Прямые m и n пересекаются в точке A. Точка B принадлежит прямой m, точка C — прямой n, точка D — прямой BC. Докажите, что прямые m и n и точка D лежат в одной плоскости.',
 'Докажи принадлежность D плоскости пересекающихся прямых m и n.',model(p,[['B','_m'],['C','_n'],['B','C']],{'plane':view('Плоскость m и n',polygon=['A','B','C']), 'bc':view('BC лежит в той же плоскости',segments=[['B','C']],points=['D'])},labels=['A','B','C','D'],planar=True),[
 step('Плоскость двух прямых','Как использовать пересечение m и n в A?','Пересекающиеся прямые m,n определяют единственную плоскость α.','Теорема 2.2.','plane'),
 step('Прямая BC','Какие её точки лежат в α?','B∈m⊂α и C∈n⊂α. Поэтому прямая BC лежит в α.','Аксиома A3.','bc'),
 step('Точка D','Как перейти от принадлежности прямой к принадлежности её точки?','D∈BC и BC⊂α, следовательно, D∈α. Итак, α содержит m, n и D.','Принадлежность каждой точки прямой содержащей её плоскости.','bc')], 'Сначала помести BC в плоскость m и n, затем используй D∈BC.')

p={'A':[0,0,3],'B':[-2,0,0],'C':[1,0,0],'D':[2,-1.5,0],'E':[1.5,-.5,0],'X':[1.25,0,0]};a=plane(p,xmin=-3,xmax=3,ymin=-2,ymax=1)
lesson(9,'Пересечение DE с плоскостью ABC','Прямые AB и AC пересекают плоскость α в точках B и C; точки D и E принадлежат α (рис. 2.3). Постройте точку пересечения DE с плоскостью ABC.',
 'Построй искомую точку через линию пересечения двух плоскостей.',model(p,[['A','B'],['A','C'],['D','E']],{'line':view('BC — общая прямая α и ABC',segments=[['B','X']],polygon=['A','B','C']), 'answer':view('Продлим DE до X на BC',segments=[['D','X']],points=['X'])},faces=[a]),[
 step('Общая прямая плоскостей','Какие две разные точки принадлежат и α, и ABC?','Это B и C. Плоскости различны, потому что A∉α. Следовательно, линия их пересечения — BC. Проведём BC.','Аксиомы A3 и A4; AB и AC пересекают α только в B,C.','line'),
 step('Построим пересечение в α','Где теперь достаточно пересечь две прямые?','DE лежит в α. Найдём X=DE∩BC, продолжая прямые при необходимости. Для положения рисунка 2.3 пересечение существует.','Построение пересечения прямых в одной плоскости.','answer'),
 step('Проверим ответ и особые случаи','Почему X — точка пересечения DE с ABC?','X∈DE и X∈BC⊂ABC, значит, X искомая. Любая общая точка DE и ABC должна лежать на BC. Если бы DE∥BC и не совпадала с BC, общей точки не было бы; при DE=BC вся прямая лежала бы в ABC.','Любая общая точка двух плоскостей лежит на их линии пересечения.','answer')], 'Не ищи пересечение прямой с нарисованным краем плоскости. Сначала проведи настоящую общую прямую BC.')

p={'A':[-2,0,0],'C':[2,0,0],'B':[0,0,3],'D':[-.4,0,2.4],'E':[1.2,0,1.2],'X':[2.8,0,0]};a=plane(p,xmin=-3,xmax=3.6,ymin=-1.2,ymax=1.2)
lesson(10,'Продолжение DE до плоскости','Прямая BA пересекает плоскость α в A, прямая BC — в C (рис. 2.4). На AB отметили D, на BC — E. Постройте точку пересечения DE с α.',
 'Построй пересечение DE и α для расположения рисунка 2.4.',model(p,[['A','B'],['B','C'],['D','E']],{'plane':view('DE лежит в ABC; общая прямая с α — AC',polygon=['A','B','C'],segments=[['A','X']]), 'answer':view('X=DE∩AC',segments=[['D','X']],points=['X'])},faces=[a]),[
 step('Найдём вспомогательную плоскость','В какой плоскости лежат D и E?','D∈AB и E∈BC, значит, обе точки лежат в плоскости ABC. Поэтому DE⊂ABC.','Аксиома A3.','plane'),
 step('Найдём общую прямую','По какой прямой пересекаются ABC и α?','A,C принадлежат обеим плоскостям, а B∉α. Поэтому ABC∩α=AC. Проведём AC.','Аксиомы A3 и A4.','plane'),
 step('Построим X','Как свести построение к двум прямым?','Продлим DE до пересечения с AC; получим X. Тогда X∈DE и X∈AC⊂α, поэтому X — искомая точка. В модели она находится на продолжении AC за C.','Пересечение двух прямых во вспомогательной плоскости.','answer'),
 step('Проверим возможность построения','Всегда ли DE обязательно пересекает AC?','Для рисунка 2.4 — да. Если выбрать D,E так, что DE∥AC и DE≠AC, то DE не пересекает α. Если D=A и E=C, то DE совпадает с AC и целиком лежит в α.','Общая точка DE и α должна лежать на ABC∩α=AC.','answer')], 'Нарисуй AC: это линия пересечения плоскости треугольника с α.')

p={'A':[-2,0,0],'B':[0,0,0],'C':[2,0,0],'D':[0,2,0],'E':[0,0,2]}
lesson(11,'Сколько точек может лежать на прямой?','Даны пять точек, не лежащих в одной плоскости. Какое наибольшее количество из них может лежать на одной прямой?',
 'Найди наибольшее число точек на одной прямой.',model(p,[['A','C']],{'plane':view('Три точки на AC и точка D задают плоскость',polygon=['A','C','D']), 'outside':view('Пятая точка E вне этой плоскости',points=['E'])}),[
 step('Почему не четыре?','Предположи, что четыре точки лежат на одной прямой. Где пятая?','Если пятая точка вне прямой, она вместе с прямой задаёт плоскость, содержащую все пять точек. Если пятая также на прямой, все пять тем более лежат в одной плоскости. Оба случая противоречат условию.','Теорема 2.1; через прямую можно провести плоскость.','plane'),
 step('Можно ли взять три?','Расположи A,B,C на одной прямой, а D — вне неё.','Прямая AC и точка D задают плоскость α. Выберем E вне α. Тогда никакая плоскость не содержит все пять точек: содержащая AC и D обязана быть именно α.','Единственность плоскости через прямую и внешнюю точку.','outside'),
 step('Сравним запрет и пример','Какой ответ теперь доказан с обеих сторон?','Четыре и пять точек на одной прямой невозможны, а три возможны. Наибольшее количество — 3.','Верхняя граница и пример её достижения.','outside')], 'Нужно не только запретить четыре точки на прямой, но и показать возможное расположение трёх.',accepted=['3'])

p={'O':[0,0,0],'A':[2,0,0],'B':[0,2,0],'C':[0,0,2]}
lesson(12,'Одна или три плоскости','Три прямые пересекаются в одной точке. Через каждые две из этих прямых проведена плоскость. Сколько всего плоскостей проведено?',
 'Укажи все возможные количества различных плоскостей и объясни, почему двух быть не может.',model(p,[['O','A'],['O','B'],['O','C']],{'ab':view('Плоскость OA и OB',polygon=['O','A','B']), 'ac':view('Плоскость OA и OC',polygon=['O','A','C']), 'bc':view('Плоскость OB и OC',polygon=['O','B','C'])}),[
 step('Если прямые в одной плоскости','Какие плоскости зададут три пары?','Если все три различные прямые лежат в одной плоскости α, то каждая пара задаёт именно α. Получается одна различная плоскость.','Единственность плоскости через две пересекающиеся прямые.','ab'),
 step('Если общей плоскости нет','Что изображено в пространственной модели?','Три оси OA,OB,OC не лежат в одной плоскости. Каждая из трёх пар определяет свою плоскость: OAB, OAC и OBC. Получаются три различные плоскости.','Теорема 2.2.','ac'),
 step('Почему не две?','Что означало бы совпадение двух из трёх плоскостей?','Любые две пары из трёх прямых вместе включают все три прямые. Если их плоскости совпали, эта общая плоскость содержит все три прямые. Тогда третья пара тоже задаёт её. Итак, возможно только 1 или 3.','Теорема 2.2 и разбор всех пар.','bc')], 'Считай различные плоскости: три выбора пары не всегда дают три разных результата.',caption='Модель показывает случай трёх различных плоскостей через три общие оси. Во втором возможном случае все три прямые находятся в одной плоскости.')

p={'A':[-2,-1,0],'B':[2,-1,0],'C':[2,1,0],'D':[-2,1,0],'O':[0,0,0]}
lesson(13,'Две нити для четырёх ножек','Как при помощи двух нитей столяр может проверить, лежат ли концы четырёх ножек стула в одной плоскости?',
 'Опиши проверку и объясни, почему она работает.',model(p,[['A','C'],['B','D']],{'threads':view('Натянутые нити между противоположными концами',segments=[['A','C'],['B','D']],points=['O']), 'plane':view('Две пересекающиеся нити задают общую плоскость',polygon=['A','B','C','D'])},planar=True),[
 step('Натянем нити по диагоналям','Какие пары концов ножек нужно соединить?','Обозначим концы ножек по порядку A,B,C,D. Одну нить натянем между противоположными концами A,C, другую — между B,D. Нити должны быть прямыми и натянутыми.','Натянутая нить моделирует отрезок.','threads','definition'),
 step('Проверим контакт','Что должно происходить в месте перекрещивания?','Если натянутые нити действительно касаются в точке O без отклонения и прогиба, прямые AC и BD пересекаются. Две пересекающиеся прямые лежат в одной плоскости, а значит, в ней лежат все четыре конца.','Теорема 2.2.','plane'),
 step('Почему зазор означает проблему?','Что было бы, если бы все четыре конца уже лежали в общей плоскости?','Для обычного стула концы расположены как вершины выпуклого четырёхугольника. В общей плоскости его диагонали пересекаются, поэтому натянутые нити соприкасаются. Если одна проходит выше другой с зазором, общей плоскости нет. Нельзя прижимать нити друг к другу: это исказит проверку.','Диагонали выпуклого четырёхугольника пересекаются.','threads')], 'Соедини противоположные ножки и проверь настоящий контакт нитей, а не пересечение их изображений при взгляде сверху.',caption='Вид сверху на концы ножек в случае удачной проверки. Нити AC и BD прямые и касаются в O; рисунок предполагает обычное выпуклое расположение четырёх ножек.')

p={'B':[0,0,3],'A':[-1,0,1.5],'C':[1,0,2],'D':[.1,0,0],'E':[-2,0,0],'F':[3,0,0]};a=plane(p,xmin=-3,xmax=4,ymin=-1,ymax=1)
lesson(14,'Исправляем рисунок 2.5','На рисунке 2.5 D принадлежит плоскости α, вершины A,B,C четырёхугольника ABCD находятся вне α; AB пересекает α в E, а BC — в F. В исходном рисунке E,D,F показаны не на одной прямой. Объясните ошибку и выполните правильный рисунок; модель здесь уже показывает исправленную конфигурацию.',
 'Объясни ошибку и укажи правильное взаимное расположение E,D,F.',model(p,[['A','B'],['B','C'],['C','D'],['D','A'],['A','E'],['C','F']],{'quad':view('Четырёхугольник ABCD лежит в одной плоскости',polygon=['A','B','C','D']), 'trace':view('Общая прямая двух плоскостей проходит через E,D,F',segments=[['E','F']],points=['D'])},faces=[a]),[
 step('Плоскость четырёхугольника','В какой плоскости лежат его стороны и их продолжения?','Обозначим плоскость четырёхугольника через β. Точки E∈AB и F∈BC принадлежат β; D как вершина также принадлежит β.','Четырёхугольник — плоская фигура; продолжения его сторон лежат в его плоскости.','quad','definition'),
 step('Три общие точки','Какая ещё плоскость содержит E,D,F?','Все три точки по условию лежат в α. Значит, E,D,F — общие точки α и β. Плоскости различны, так как A,B,C∉α.','Условие задачи.','trace','given'),
 step('Исправим ошибку','Как должны располагаться три общие точки разных плоскостей?','Они должны лежать на одной прямой α∩β. На рисунке 2.5 D не находится на прямой EF — в этом ошибка. Правильная модель размещает E,D,F на одной прямой; для расположения рисунка D лежит между E и F.','Аксиома A4: две различные пересекающиеся плоскости пересекаются по прямой.','trace')], 'Точки E,D,F одновременно принадлежат плоскости четырёхугольника и плоскости α.',caption='Показан исправленный рисунок 2.5: E,D,F лежат на общей прямой двух плоскостей. Это корректная модель исходных условий; ошибочный чертёж учебника намеренно не воспроизводится.')

def intersect2(a,b,c,d):
    u=[b[0]-a[0],b[1]-a[1]];v=[d[0]-c[0],d[1]-c[1]]
    w=[c[0]-a[0],c[1]-a[1]];den=u[0]*v[1]-u[1]*v[0]
    t=(w[0]*v[1]-w[1]*v[0])/den
    return [a[0]+t*u[0],a[1]+t*u[1]]
flat={'A':[0,0],'B':[0,1.5],'C':[0,3],'F':[3,4],'M':[4,0],'P':[3.4,2.4],'K':[3.7,1.2]}
flat['E']=intersect2(flat['B'],flat['P'],flat['C'],flat['K'])
flat['D']=intersect2(flat['F'],flat['E'],[0,0],[4,0])
p={k:[q[0],0,q[1]] for k,q in flat.items()};a=plane(p,xmin=-1,xmax=5,ymin=-1,ymax=1)
lesson(15,'Исправляем рисунок 2.6','На рисунке 2.6 прямые BP и CK пересекаются в E; BP пересекает AC в B и FM в P, CK пересекает FM в K. Прямые AC, FE и FM пересекают плоскость α в A,D,M соответственно. В исходном рисунке A,D,M показаны не на одной прямой. Объясните ошибку и выполните правильный рисунок; модель здесь уже показывает исправленную конфигурацию.',
 'Объясни, почему A,D,M обязаны лежать на одной прямой.',model(p,[['A','C'],['F','M'],['B','P'],['C','K'],['F','D']],{'cross':view('Пересекающиеся BP и CK задают β',segments=[['B','P'],['C','K']],points=['E']), 'lines':view('AC,FM и FE лежат в β',segments=[['A','C'],['F','M'],['F','D']]), 'trace':view('Правильное расположение A,D,M',segments=[['A','M']],points=['D'])},faces=[a],labels=['A','B','C','D','E','F','K','M','P']),[
 step('Зададим плоскость β','Какие две пересекающиеся прямые удобнее взять?','BP и CK пересекаются в E, поэтому определяют плоскость β. Точки B,P,C,K,E лежат в β.','Теорема 2.2.','cross'),
 step('Поместим AC и FM в β','Какие две точки каждой прямой уже известны?','B,C принадлежат AC и β, значит, AC⊂β. Точки P,K принадлежат FM и β, значит, FM⊂β. Поэтому A,C,F,M также принадлежат β.','Аксиома A3; на рисунке B≠C и P≠K.','lines'),
 step('Поместим FE в β','Почему точка D тоже лежит в β?','F∈FM⊂β и E∈β, следовательно, FE⊂β. Так как D∈FE, получаем D∈β.','Аксиома A3.','lines'),
 step('Исправим линию пересечения','Что объединяет A,D,M?','A,D,M принадлежат и α, и β. Плоскости различны: например, F∉α, так как FM пересекает α только в M. Поэтому A,D,M должны лежать на одной прямой α∩β. На исходном рисунке D изображена вне AM — это ошибка. В правильной модели D перенесена на общую прямую с сохранением всех указанных пересечений.','Аксиома A4.','trace')], 'Сначала докажи, что все прямые рисунка лежат в одной вспомогательной плоскости. После этого сравни её с α.',caption='Исправленная конфигурация рисунка 2.6. Все заявленные пересечения сохранены; A,D,M находятся на одной прямой. Для просмотра отдельных шагов подсвечивается только нужная часть построения.')

p={'A':[-2,0,0],'B':[2,0,0],'C':[.6,0,0],'D':[0,2,0],'E':[-1,1,0]}
lesson(16,'Совпадение двух плоскостей','Точка C лежит на прямой AB, а D не лежит на этой прямой. Точка E лежит на AD. Докажите, что плоскости ABD и CDE совпадают.',
 'Докажи совпадение плоскостей, используя принадлежности точек.',model(p,[['A','B'],['A','D'],['D','C']],{'abd':view('Плоскость ABD',polygon=['A','B','D']), 'cde':view('Три точки C,D,E лежат в ABD',polygon=['C','D','E'])},planar=True),[
 step('Выберем плоскость ABD','Почему она определена?','D не лежит на AB, поэтому точки A,B,D неколлинеарны и определяют единственную плоскость α=ABD.','Аксиома A2; теорема 2.1.','abd'),
 step('Проверим C и E','Почему обе точки принадлежат α?','C∈AB⊂α, поэтому C∈α. Точки A,D лежат в α, следовательно AD⊂α; из E∈AD получаем E∈α. Конечно, D∈α.','Аксиома A3.','cde'),
 step('Применим единственность','Какая плоскость определяется C,D,E?','По смыслу обозначения «плоскость CDE» эти три точки неколлинеарны. Все они принадлежат α, поэтому их единственная плоскость CDE совпадает с α=ABD. Если допустить вырожденный выбор, например C=A, название «плоскость CDE» не определяет единственную плоскость; такой выбор не входит в невырожденную конфигурацию задачи.','Аксиома A2 и условие корректности обозначения плоскости тремя точками.','cde')], 'Сначала покажи C,D,E∈ABD. Затем проверь, какие условия нужны для единственности плоскости CDE.')

p={'A':[-2,0,0],'B':[2,0,0],'C':[0,2,0]}
lesson(17,'Три попарно пересекающиеся прямые','Прямые a,b,c попарно пересекаются, причём точки их пересечения не совпадают. Лежат ли прямые a,b,c в одной плоскости?',
 'Докажи ответ и объясни, зачем нужны разные точки пересечения.',model(p,[['A','B'],['A','C'],['B','C']],{'plane':view('a=AB и b=AC задают α',polygon=['A','B','C']), 'third':view('c=BC имеет две разные точки в α',segments=[['B','C']])},planar=True),[
 step('Обозначим пересечения','Какие три точки удобно ввести?','Пусть A=a∩b, B=a∩c, C=b∩c. По условию эти точки различны. Прямые a,b определяют плоскость α.','Условие задачи и теорема 2.2.','plane'),
 step('Поместим третью прямую в α','Почему у c есть две разные точки в этой плоскости?','B∈a⊂α и C∈b⊂α. При этом B≠C. Прямая c проходит через B,C, поэтому целиком лежит в α.','Аксиома A3.','third'),
 step('Сформулируем вывод','Что изменилось бы, если бы все пересечения совпали?','Ответ: да, a,b,c лежат в одной плоскости. Условие о разных точках существенно: три пространственные оси пересекаются в одной точке, но общей плоскости не имеют.','Доказательство выше; контрпример показывает необходимость условия.','plane')], 'Возьми плоскость первых двух прямых и найди на третьей две разные точки этой плоскости.')

flat={'A':[0,0],'B':[1.5,3],'C':[4,0],'E':[-2,0],'P':[5.2,-1.44],'Q':[2.2,4.4],'K':[2.8,.2]}
flat['M']=[flat['K'][i]-.4*(flat['P'][i]-flat['K'][i]) for i in range(2)]
flat['N']=intersect2(flat['E'],flat['M'],flat['Q'],flat['K'])
p={k:[q[0],q[1],0] for k,q in flat.items()}
lesson(18,'Три общие неколлинеарные точки','На рисунке 2.7 P,E,Q — точки пересечения MK и BC, MN и CA, KN и AB соответственно. На рисунке E лежит на продолжении AC за A, Q — на продолжении AB за B, P — на продолжении BC за C; E,P,Q неколлинеарны. Верно ли, что плоскости ABC и MNK совпадают?',
 'Дай ответ для расположения рисунка 2.7 и объясни его.',model(p,[['A','Q'],['B','P'],['E','C'],['M','P'],['E','N'],['Q','K']],{'common':view('E,P,Q принадлежат обеим плоскостям',points=['E','P','Q']), 'outer':view('Плоскость ABC',polygon=['A','B','C']), 'inner':view('Плоскость MNK',polygon=['M','N','K'])},labels=['A','B','C','E','P','Q','M','N','K'],planar=True),[
 step('Найдём общие точки','Почему P принадлежит обеим плоскостям?','P∈BC⊂ABC и P∈MK⊂MNK. Аналогично, E∈CA и E∈MN, а Q∈AB и Q∈KN. Поэтому E,P,Q принадлежат обеим плоскостям.','Принадлежности, заданные рисунком 2.7.','common','given'),
 step('Проверим расположение трёх точек','Лежат ли E,P,Q на одной прямой на рисунке 2.7?','Нет. В изображённой конфигурации E,P,Q неколлинеарны: E на продолжении AC за A, Q на продолжении AB за B, P на продолжении BC за C. В частности, прямая PQ пересекает продолжение AC за C, а не в E.','Расположение точек на рисунке 2.7.','outer','given'),
 step('Применим единственность','Сколько плоскостей может содержать три неколлинеарные общие точки?','Ровно одна. Значит, ABC и MNK совпадают. Ответ для данного рисунка: да. Если забыть рисунок и оставить только названия трёх пересечений, нужно дополнительно проверить неколлинеарность E,P,Q: три общие точки на одной прямой ещё не доказывают совпадение плоскостей.','Аксиома A2.','inner')], 'Отыщи три общие точки двух плоскостей. Для единственности обязательно проверь, что они не лежат на одной прямой.',caption='Восстановлена плоская конфигурация рисунка 2.7: E=MN∩CA, P=MK∩BC, Q=KN∩AB; E,P,Q не лежат на одной прямой. На каждом шаге выделяется нужная группа точек.')

p={'A':[0,0,0],'B':[2,4,0],'C':[10,4,0],'D':[8,0,0],'M':[6,4,0],'H':[6,0,0]}
lesson(19,'Общая высота треугольника и параллелограмма','На стороне BC параллелограмма ABCD отметили M. Найдите площадь ABCD, если площадь треугольника AMD равна 16 см².',
 'Найди площадь параллелограмма ABCD в см².',model(p,[['A','B'],['B','C'],['C','D'],['D','A'],['A','M'],['M','D']],{'triangle':view('Треугольник AMD: основание AD и высота MH',polygon=['A','D','M'],segments=[['M','H']]), 'par':view('У параллелограмма то же основание и та же высота',polygon=['A','B','C','D'],segments=[['M','H']])},planar=True),[
 step('Сравним высоты','Почему высота из M равна высоте параллелограмма?','M лежит на BC, а BC∥AD. Расстояние между параллельными прямыми BC и AD постоянно. Поэтому высота MH треугольника AMD к AD равна высоте параллелограмма к тому же основанию.','Расстояние между параллельными прямыми.','triangle'),
 step('Запишем площади','Чем отличаются формулы при одинаковых основании и высоте?','S(AMD)=AD·MH/2, а S(ABCD)=AD·MH. Поэтому площадь параллелограмма в 2 раза больше площади треугольника.','Формулы площадей треугольника и параллелограмма.','par'),
 step('Вычислим','Как из 16 см² получить площадь параллелограмма?','S(ABCD)=2·16=32 см². Ответ: 32. Положение M на BC не меняет высоту и результат.','Подстановка известной площади.','par')], 'Выбери основание AD для обеих фигур и сравни их высоты.',accepted=['32'])

p={'E':[0,0,0],'A':[-6,-8,0],'B':[3,4,0],'C':[0,-3,0],'D':[0,6,0]}
lesson(20,'Подобие треугольников при параллельных прямых','Отрезки AB и CD пересекаются в E; AD∥BC. Найдите BE, если AE=10 см, CE=3 см, DE=6 см.',
 'Найди длину BE в сантиметрах.',model(p,[['A','B'],['C','D'],['A','D'],['B','C']],{'first':view('Треугольник AED',polygon=['A','E','D']), 'second':view('Соответствующий треугольник BEC',polygon=['B','E','C']), 'ratio':view('AE соответствует BE, DE соответствует CE',segments=[['A','E'],['E','B'],['D','E'],['E','C']])},planar=True),[
 step('Найдём равные углы','Какие углы равны при пересечении AB и CD?','∠AED=∠BEC как вертикальные. Кроме того, ∠ADE=∠BCE как накрест лежащие при AD∥BC и секущей CD.','Вертикальные углы; углы при параллельных прямых.','first'),
 step('Установим подобие','В каком порядке соответствуют вершины?','Треугольники AED и BEC подобны по двум углам: A↔B, E↔E, D↔C. Поэтому AE соответствует BE, а DE — CE.','Признак подобия треугольников по двум углам.','second'),
 step('Составим пропорцию','Сравни стороны первого треугольника с соответствующими сторонами второго.','AE/BE=DE/CE. Подставляем: 10/BE=6/3=2. Следовательно, BE=10/2=5 см.','Пропорциональность соответствующих сторон подобных треугольников.','ratio'),
 step('Проверим результат','Одинаково ли уменьшились соответствующие стороны?','DE=6 см уменьшилось до CE=3 см в 2 раза. AE=10 см также должно уменьшиться в 2 раза: получаем BE=5 см. Ответ: 5.','Проверка коэффициента подобия.','ratio')], 'Сначала выпиши соответствие вершин A↔B, D↔C, E↔E, чтобы не перевернуть одну из дробей.',accepted=['5'])

